import { useRef, useState } from "react";

export default function BigActions() {
  const [message, setMessage] = useState("");
  const ctx = useRef(null);
  const last = useRef(0);

  function tone(freq) {
    if (performance.now() - last.current < 80) return;
    last.current = performance.now();
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    ctx.current = ctx.current || new AC();
    const now = ctx.current.currentTime;
    const osc = ctx.current.createOscillator();
    const amp = ctx.current.createGain();
    osc.frequency.value = freq;
    amp.gain.setValueAtTime(0.0001, now);
    amp.gain.exponentialRampToValueAtTime(0.05, now + 0.01);
    amp.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);
    osc.connect(amp).connect(ctx.current.destination);
    osc.start(now);
    osc.stop(now + 0.09);
  }

  function press(label, freq, messageText) {
    setMessage(messageText);
    tone(freq);
  }

  return (
    <div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 12, justifyContent: "center" }}>
        <button type="button" onClick={() => press("confirm", 880, "Confirmed. Your change is saved.")} style={{ minHeight: 56, padding: "0 24px", borderRadius: 14, border: "2px solid #FFD84D", background: "#FFD84D", color: "#10130A", fontSize: 19, fontWeight: 700, cursor: "pointer" }}>
          Confirm
        </button>
        <button type="button" onClick={() => press("cancel", 520, "Cancelled. Nothing was changed.")} style={{ minHeight: 56, padding: "0 24px", borderRadius: 14, border: "2px solid #46586C", background: "#141C25", color: "#F3F6F9", fontSize: 19, fontWeight: 700, cursor: "pointer" }}>
          Cancel
        </button>
        <button type="button" onClick={() => press("help", 520, "A staff member has been called.")} style={{ minHeight: 56, padding: "0 24px", borderRadius: 14, border: "2px solid #46586C", background: "#141C25", color: "#F3F6F9", fontSize: 19, fontWeight: 700, cursor: "pointer" }}>
          Help
        </button>
      </div>
      <p role="status" aria-live="polite" style={{ minHeight: "1.5em", marginTop: 18, textAlign: "center", color: "#BAC5D1" }}>
        {message}
      </p>
    </div>
  );
}

import { useEffect, useState } from "react";

const KEY = "a11y-text-settings";

export default function TextScaleSwitch() {
  const [size, setSize] = useState(100);
  const [contrast, setContrast] = useState(false);

  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(KEY) || "{}");
      if (saved.size) setSize(saved.size);
      if (saved.contrast) setContrast(true);
    } catch (e) {}
  }, []);

  function save(patch) {
    try {
      const next = Object.assign({}, JSON.parse(localStorage.getItem(KEY) || "{}"), patch);
      localStorage.setItem(KEY, JSON.stringify(next));
    } catch (e) {}
  }

  const dark = contrast;

  return (
    <div style={{ padding: 22, borderRadius: 16, border: dark ? "2px solid #fff" : "1px solid #2B3644", background: dark ? "#000" : "#0E141B", color: dark ? "#fff" : "#F3F6F9", fontSize: 17 * (size / 100) }}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, alignItems: "center", marginBottom: 18 }}>
        <div role="group" aria-label="Text size" style={{ display: "inline-flex", border: "1.5px solid #46586C", borderRadius: 999, overflow: "hidden" }}>
          {[100, 125, 150].map((value) => (
            <button key={value} type="button" aria-pressed={size === value} onClick={() => { setSize(value); save({ size: value }); }} style={{ minWidth: 46, minHeight: 44, border: 0, background: size === value ? "#FFD84D" : "transparent", color: size === value ? "#10130A" : "inherit", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
              {value === 100 ? "A" : value === 125 ? "A+" : "A++"}
            </button>
          ))}
        </div>
        <button type="button" role="switch" aria-checked={contrast} onClick={() => { const on = !contrast; setContrast(on); save({ contrast: on }); }} style={{ display: "inline-flex", alignItems: "center", gap: 10, minHeight: 44, border: 0, background: "transparent", color: "inherit", fontSize: 14, fontWeight: 650, cursor: "pointer" }}>
          <span aria-hidden="true" style={{ position: "relative", width: 64, height: 34, borderRadius: 999, border: "2px solid #46586C", background: contrast ? "#7CF2B0" : "#141C25" }}>
            <span style={{ position: "absolute", top: 2, left: 2, width: 26, height: 26, borderRadius: "50%", background: contrast ? "#052015" : "#F3F6F9", transform: contrast ? "translateX(30px)" : "none", transition: "transform .16s" }} />
          </span>
          High contrast
        </button>
      </div>
      <p style={{ margin: "0 0 6px", fontSize: "2em", fontWeight: 800, lineHeight: 1.1 }}>8:30 AM</p>
      <p style={{ margin: "0 0 6px" }}>One blood-pressure tablet with a glass of water.</p>
      <p style={{ margin: 0, color: dark ? "#fff" : "#BAC5D1", fontSize: ".92em" }}>Any time within 30 minutes after breakfast.</p>
    </div>
  );
}

