export default function MedicationChecklist() {
  const [taken, setTaken] = useState([]);
  const count = taken.length;

  function toggle(time) {
    setTaken((prev) => (prev.includes(time) ? prev.filter((t) => t !== time) : prev.concat(time)));
  }

  return (
    <div style={{ width: "min(460px, 100%)", color: "#F3F6F9" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
        <p style={{ margin: 0, fontWeight: 750 }}>Wednesday 18 Nov</p>
        <p role="status" aria-live="polite" style={{ margin: 0, color: "#FFD84D", fontWeight: 800, fontSize: ".85rem" }}>
          {count === 0 ? "None taken yet" : count + " of " + DOSES.length + " taken"}
        </p>
      </div>
      <ul style={{ listStyle: "none", margin: "12px 0 0", padding: 0, display: "grid", gap: 8 }}>
        {DOSES.map((dose) => {
          const isTaken = taken.includes(dose.time);
          return (
            <li key={dose.time}>
              <button type="button" aria-pressed={isTaken} onClick={() => toggle(dose.time)} style={{ display: "grid", gridTemplateColumns: "auto 1fr auto", gap: 12, alignItems: "center", width: "100%", minHeight: 64, padding: "10px 14px", borderRadius: 12, border: isTaken ? "2px solid #7CF2B0" : "2px solid #46586C", background: isTaken ? "#0E2419" : "#141C25", color: "#F3F6F9", font: "inherit", textAlign: "left", cursor: "pointer" }}>
                <span style={{ color: isTaken ? "#7CF2B0" : "#FFD84D", fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{dose.time}</span>
                <span style={{ fontWeight: 650 }}>{dose.name}</span>
                <span style={{ fontSize: ".72rem", fontWeight: 800, textTransform: "uppercase", letterSpacing: ".06em", border: isTaken ? "1.5px solid #7CF2B0" : "1.5px solid #46586C", background: isTaken ? "#7CF2B0" : "transparent", color: isTaken ? "#052015" : "inherit", borderRadius: 999, padding: ".35em .7em" }}>
                  {isTaken ? "Taken" : "Take"}
                </span>
              </button>
            </li>
          );
        })}
