import { useRef, useState } from "react";

const OPTIONS = ["Book an appointment", "Pay a bill", "Print a document", "Ask a person for help"];

export default function KioskChoiceList() {
  const [selected, setSelected] = useState(0);
  const refs = useRef([]);

  function choose(index) {
    setSelected(index);
    refs.current[index]?.focus();
  }

  function onKeyDown(event, index) {
    const last = OPTIONS.length - 1;
    if (event.key === "ArrowDown" || event.key === "ArrowRight") {
      event.preventDefault();
      choose(index === last ? 0 : index + 1);
    } else if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
      event.preventDefault();
      choose(index === 0 ? last : index - 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      choose(0);
    } else if (event.key === "End") {
      event.preventDefault();
      choose(last);
    } else if (event.key === " " || event.key === "Enter") {
      event.preventDefault();
      setSelected(index);
    }
  }

  return (
    <fieldset style={{ width: "min(460px, 100%)", margin: 0, padding: 0, border: 0 }}>
      <legend style={{ padding: 0, marginBottom: 10, fontSize: "1.08rem", fontWeight: 750, color: "#F3F6F9" }}>
        How can we help?
      </legend>
      <div role="radiogroup" aria-label="Kiosk menu" style={{ display: "grid", gap: 8 }}>
        {OPTIONS.map((label, index) => {
          const on = selected === index;
          return (
            <button
              key={label}
              ref={(el) => { refs.current[index] = el; }}
              type="button"
              role="radio"
              aria-checked={on}
              tabIndex={on ? 0 : -1}
              onClick={() => setSelected(index)}
              onKeyDown={(event) => onKeyDown(event, index)}
              style={{ display: "flex", alignItems: "center", gap: 13, width: "100%", minHeight: 64, padding: "10px 15px", borderRadius: 14, border: on ? "2px solid #FFD84D" : "2px solid #46586C", background: on ? "#26200A" : "#141C25", color: "#F3F6F9", fontSize: "1.02rem", fontWeight: 650, textAlign: "left", cursor: "pointer" }}
            >
              <span aria-hidden="true" style={{ fontSize: ".78rem", color: on ? "#10130A" : "#BAC5D1", background: on ? "#FFD84D" : "transparent", border: "1px solid " + (on ? "#FFD84D" : "#2B3644"), borderRadius: 6, padding: ".1em .4em" }}>
                {index + 1}
              </span>
              <span>{label}</span>
              {on ? <span aria-hidden="true" style={{ marginLeft: "auto", color: "#FFD84D", fontWeight: 900 }}>✓</span> : null}
            </button>
          );
        })}
      </div>
      <p role="status" aria-live="polite" style={{ margin: "14px 0 0", minHeight: "1.4em", color: "#BAC5D1", fontSize: ".9rem" }}>
        Selected: {OPTIONS[selected]}. Press Next to continue.
      </p>
    </fieldset>
  );
}

import { useEffect, useRef, useState } from "react";

const TEXT = "Your appointment is Thursday 20 November at 2:30 PM with Dr. Park, room 302. Please bring your ID card.";

export default function ReadAloud() {
  const [status, setStatus] = useState("");
  const [rate, setRate] = useState(0.9);
  const supported = typeof window !== "undefined" && "speechSynthesis" in window;

  useEffect(() => {
    if (!supported) setStatus("This browser has no speech voice. The text above is the full content.");
    return () => {
      if (supported) window.speechSynthesis.cancel();
    };
  }, [supported]);

  function speak() {
    if (!supported) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(TEXT);
    utterance.lang = document.documentElement.lang || "en-US";
    utterance.rate = rate;
    setStatus("Reading aloud. Press Stop to end it.");
    utterance.onend = () => setStatus("Finished reading.");
    utterance.onerror = () => setStatus("This browser could not read the text.");
    window.speechSynthesis.speak(utterance);
  }

  function stop() {
    if (!supported) return;
    window.speechSynthesis.cancel();
    setStatus("Stopped.");
  }

  return (
    <div style={{ width: "min(540px, 100%)", color: "#F3F6F9" }}>
      <blockquote style={{ margin: 0, padding: 16, borderLeft: "4px solid #FFD84D", borderRadius: "0 12px 12px 0", background: "#141C25", fontSize: "1.05rem", lineHeight: 1.6 }}>
        {TEXT}
      </blockquote>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 10, marginTop: 14 }}>
        <button type="button" onClick={speak} style={{ minHeight: 56, padding: "0 20px", borderRadius: 14, border: "2px solid #FFD84D", background: "#FFD84D", color: "#10130A", fontWeight: 700, cursor: "pointer" }}>
          Read aloud
        </button>
        <button type="button" onClick={stop} style={{ minHeight: 56, padding: "0 20px", borderRadius: 14, border: "2px solid #46586C", background: "#141C25", color: "#F3F6F9", fontWeight: 700, cursor: "pointer" }}>
          Stop
        </button>
        <label style={{ display: "inline-flex", alignItems: "center", gap: 8, color: "#BAC5D1", fontSize: ".9rem", minHeight: 56 }}>
          Speed
          <select value={rate} onChange={(event) => setRate(Number(event.target.value))} style={{ font: "inherit", minHeight: 48, padding: ".4em .6em", borderRadius: 10, border: "2px solid #46586C", background: "#141C25", color: "#F3F6F9" }}>
            <option value={0.7}>Slow</option>
            <option value={0.9}>Normal</option>
            <option value={1.1}>Fast</option>
          </select>
        </label>
      </div>
      <p role="status" aria-live="polite" style={{ minHeight: "1.4em", color: "#BAC5D1", fontSize: ".9rem", marginTop: 12 }}>{status}</p>
    </div>
  );
}

import { useRef, useState } from "react";

export default function ConfirmSwitch() {
