    dialogRef.current?.close();
    setStatus(message);
  }

  return (
    <div>
      <p style={{ margin: 0, fontWeight: 700 }}>Delete 14 photos from the family album?</p>
      <button type="button" onClick={open} style={{ minHeight: 56, marginTop: 12, padding: "0 22px", borderRadius: 14, border: "2px solid #FF9A9A", background: "#FF9A9A", color: "#22090A", fontWeight: 700, cursor: "pointer" }}>
