                  <span style={{ position: "absolute", top: 2, left: 2, width: 26, height: 26, borderRadius: "50%", background: armed ? "#052015" : "#F3F6F9", transform: armed ? "translateX(30px)" : "none", transition: "transform .16s" }} />
