import { useState } from "react";

const KEYS = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "clear", "0", "ok"];

export default function NumberKeypad() {
  const [value, setValue] = useState("");
  const [status, setStatus] = useState("Demo only — nothing is sent.");

  function press(key) {
    if (key === "clear") {
      setValue("");
      setStatus("No digits entered.");
      return;
    }
    if (key === "ok") {
      setStatus("Accepted — demo only, nothing was sent.");
      return;
    }
    if (value.length < 6) {
      const next = value + key;
      setValue(next);
      setStatus(next.length + " digits entered.");
    }
  }

  return (
    <div style={{ width: "min(320px, 100%)", color: "#F3F6F9" }}>
      <output aria-live="polite" aria-label={value ? value.length + " digits entered." : "No digits entered."} style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: 64, border: "2px solid #46586C", borderRadius: 12, background: "#05080C", color: "#FFD84D", fontFamily: "ui-monospace, Menlo, monospace", fontSize: "1.7rem", letterSpacing: ".28em" }}>
        {value ? "•".repeat(value.length) : "— — — —"}
      </output>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginTop: 12 }}>
        {KEYS.map((key) => (
          <button
            key={key}
            type="button"
            onClick={() => press(key)}
            style={{ minHeight: 64, border: key === "ok" ? "2px solid #FFD84D" : "2px solid #46586C", borderRadius: 12, background: key === "ok" ? "#FFD84D" : "#141C25", color: key === "ok" ? "#10130A" : key === "clear" ? "#BAC5D1" : "#F3F6F9", fontSize: key === "ok" || key === "clear" ? "1rem" : "1.3rem", fontWeight: 750, cursor: "pointer" }}
          >
            {key === "clear" ? "Clear" : key === "ok" ? "OK" : key}
          </button>
        ))}
      </div>
      <p role="status" aria-live="polite" style={{ minHeight: "1.4em", color: "#BAC5D1", fontSize: ".88rem", marginTop: 12 }}>{status}</p>
    </div>
  );
}

