import { useState } from "react";

const STEPS = ["Identity", "Symptoms", "Time", "Confirm"];

export default function StepProgress() {
  const [current, setCurrent] = useState(0);

  return (
    <div style={{ width: "min(520px, 100%)", color: "#F3F6F9" }}>
      <div aria-hidden="true" style={{ height: 10, border: "1px solid #2B3644", borderRadius: 999, background: "#141C25", overflow: "hidden" }}>
        <span style={{ display: "block", height: "100%", width: ((current + 1) / STEPS.length) * 100 + "%", background: "#FFD84D", transition: "width .2s" }} />
      </div>
      <ol style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6, margin: "14px 0 0", padding: 0, listStyle: "none" }}>
        {STEPS.map((name, index) => {
          const done = index < current;
          const active = index === current;
          return (
            <li key={name} aria-current={active ? "step" : undefined} style={{ display: "grid", justifyItems: "center", gap: 6, textAlign: "center", fontSize: ".78rem", color: active ? "#F3F6F9" : "#BAC5D1", fontWeight: active ? 750 : 400 }}>
              <span style={{ width: 42, height: 42, borderRadius: "50%", display: "grid", placeItems: "center", fontWeight: 800, border: "2px solid " + (done || active ? "transparent" : "#46586C"), background: done ? "#7CF2B0" : active ? "#FFD84D" : "#141C25", color: done ? "#052015" : active ? "#10130A" : "#F3F6F9" }}>
                {done ? "✓" : index + 1}
              </span>
              <span>{name}</span>
            </li>
          );
        })}
      </ol>
      <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
        <button type="button" disabled={current === 0} onClick={() => setCurrent((c) => Math.max(0, c - 1))} style={{ minHeight: 56, padding: "0 22px", borderRadius: 14, border: "2px solid #46586C", background: "#141C25", color: "#F3F6F9", fontWeight: 700, cursor: current === 0 ? "not-allowed" : "pointer", opacity: current === 0 ? 0.45 : 1 }}>
          Back
        </button>
        <button type="button" disabled={current === STEPS.length - 1} onClick={() => setCurrent((c) => Math.min(STEPS.length - 1, c + 1))} style={{ minHeight: 56, padding: "0 22px", borderRadius: 14, border: "2px solid #FFD84D", background: "#FFD84D", color: "#10130A", fontWeight: 700, cursor: current === STEPS.length - 1 ? "not-allowed" : "pointer", opacity: current === STEPS.length - 1 ? 0.45 : 1 }}>
          Next
        </button>
      </div>
      <p role="status" aria-live="polite" style={{ minHeight: "1.4em", marginTop: 12, color: "#BAC5D1", fontSize: ".88rem" }}>
        Step {current + 1} of {STEPS.length} · {STEPS[current]}
      </p>
    </div>
  );
}

import { useRef, useState } from "react";

const EMPTY = { name: "", phone: "", date: "" };

export default function SeniorForm() {
  const [values, setValues] = useState(EMPTY);
  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState("");
  const summaryRef = useRef(null);
  const refs = { name: useRef(null), phone: useRef(null), date: useRef(null) };

  function validate(next) {
    const out = {};
    if (!next.name.trim()) out.name = "Enter your name.";
    const digits = next.phone.replace(/[^0-9]/g, "");
    if (!next.phone.trim()) out.phone = "Enter a phone number.";
    else if (digits.length < 9) out.phone = "Enter at least 9 digits, numbers only.";
    if (!next.date) out.date = "Choose a date.";
    return out;
  }

  function submit(event) {
    event.preventDefault();
    const found = validate(values);
    setErrors(found);
    setStatus("");
    if (Object.keys(found).length) {
      setTimeout(() => summaryRef.current?.focus(), 0);
      return;
    }
    setStatus("Request recorded. This demo does not send anything.");
  }

  const labels = { name: "Full name", phone: "Phone number", date: "Preferred date" };
  const keys = Object.keys(labels);

  return (
    <form onSubmit={submit} noValidate style={{ width: "min(520px, 100%)", color: "#F3F6F9" }}>
      {Object.keys(errors).length ? (
        <div ref={summaryRef} tabIndex={-1} role="alert" style={{ border: "2px solid #FF9A9A", background: "#2A1013", borderRadius: 12, padding: "13px 16px", marginBottom: 15, fontSize: ".93rem" }}>
          <h2 style={{ margin: "0 0 6px", fontSize: ".95rem", color: "#FF9A9A" }}>
            Please check {Object.keys(errors).length} field{Object.keys(errors).length === 1 ? "" : "s"} below.
          </h2>
          <ul style={{ margin: 0, paddingLeft: "1.2em", display: "grid", gap: 4 }}>
            {keys.filter((k) => errors[k]).map((k) => (
              <li key={k}>
                <a href={"#" + k} onClick={(event) => { event.preventDefault(); refs[k].current?.focus(); }} style={{ color: "#F3F6F9", fontWeight: 650 }}>
                  {errors[k]}
                </a>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {keys.map((key) => (
        <div key={key} style={{ display: "grid", gap: 6, marginBottom: 15 }}>
          <label htmlFor={key} style={{ fontWeight: 750, fontSize: ".98rem" }}>{labels[key]}</label>
          <input
            id={key}
            ref={refs[key]}
            type={key === "phone" ? "tel" : key === "date" ? "date" : "text"}
            inputMode={key === "phone" ? "tel" : undefined}
            autoComplete={key === "name" ? "name" : key === "phone" ? "tel" : undefined}
            value={values[key]}
            aria-invalid={Boolean(errors[key])}
            aria-describedby={errors[key] ? key + "-err" : undefined}
            onChange={(event) => {
              const next = Object.assign({}, values, { [key]: event.target.value });
              setValues(next);
              if (errors[key]) setErrors(validate(next));
            }}
            style={{ width: "100%", minHeight: 56, padding: ".5em .7em", fontSize: "1.02rem", color: "#F3F6F9", background: "#05080C", border: errors[key] ? "3px solid #FF9A9A" : "2px solid #46586C", borderRadius: 10, fontFamily: "inherit" }}
          />
          {key === "phone" && !errors[key] ? (
            <p style={{ margin: 0, color: "#BAC5D1", fontSize: ".85rem" }}>Digits only, for example 01012345678</p>
          ) : null}
          {errors[key] ? (
            <p id={key + "-err"} style={{ margin: 0, color: "#FF9A9A", fontWeight: 700, fontSize: ".94rem" }}>⚠ {errors[key]}</p>
          ) : null}
        </div>
      ))}

      <button type="submit" style={{ minHeight: 56, width: "100%", borderRadius: 14, border: "2px solid #FFD84D", background: "#FFD84D", color: "#10130A", fontWeight: 700, cursor: "pointer" }}>
        Request a callback
      </button>
      <p role="status" aria-live="polite" style={{ minHeight: "1.4em", marginTop: 12, color: "#7CF2B0", fontSize: ".9rem" }}>{status}</p>
    </form>
  );
}
